from fastapi import FastAPI, HTTPException, Response
from pydantic import BaseModel
import json
import os
from typing import Optional

app = FastAPI()

# Data directory
DATA_DIR = "/workdir/data"

# Ensure data directory exists
os.makedirs(DATA_DIR, exist_ok=True)

# Queue storage - maps queue name to list of messages
queues = {}

class CreateQueueRequest(BaseModel):
    name: str

class SendMessageRequest(BaseModel):
    content: str

class QueueData:
    def __init__(self):
        self.messages = []

def get_queue_data(queue_name: str) -> Optional[QueueData]:
    """Get queue data from file, create if doesn't exist"""
    queue_file = os.path.join(DATA_DIR, f"{queue_name}.json")

    # Check if we have it in memory
    if queue_name in queues:
        return queues[queue_name]

    # Try to load from file
    if os.path.exists(queue_file):
        try:
            with open(queue_file, 'r') as f:
                data = json.load(f)
                # Create QueueData object and store in memory
                qd = QueueData()
                qd.messages = data.get('messages', [])
                queues[queue_name] = qd
                return qd
        except:
            pass

    # Queue doesn't exist - return None (will be created on demand)
    return None

def save_queue_data(queue_name: str, queue_data: QueueData):
    """Save queue data to file"""
    queue_file = os.path.join(DATA_DIR, f"{queue_name}.json")
    with open(queue_file, 'w') as f:
        json.dump({'messages': queue_data.messages}, f)

@app.post("/queues")
def create_queue(request: CreateQueueRequest):
    """Create a new queue"""
    queue_name = request.name
    queue_data = QueueData()
    queues[queue_name] = queue_data
    save_queue_data(queue_name, queue_data)
    return {"status": "ok", "queue": queue_name}

@app.post("/queues/{queue_name}/messages")
def send_message(queue_name: str, request: SendMessageRequest):
    """Send a message to a queue"""
    # Get or create queue
    queue_data = get_queue_data(queue_name)
    if queue_data is None:
        # Queue doesn't exist, create it
        queue_data = QueueData()
        queues[queue_name] = queue_data
        save_queue_data(queue_name, queue_data)

    # Add message to queue (FIFO - append to end)
    queue_data.messages.append(request.content)
    save_queue_data(queue_name, queue_data)
    return {"status": "ok", "message": request.content}

@app.get("/queues/{queue_name}/messages")
def receive_message(queue_name: str):
    """Receive/consume one message from queue (FIFO)"""
    # Get queue data
    queue_data = get_queue_data(queue_name)
    if queue_data is None:
        # Queue doesn't exist
        raise HTTPException(status_code=404, detail="Queue not found")

    # Check if queue is empty
    if len(queue_data.messages) == 0:
        return Response(status_code=204)

    # Get first message (FIFO)
    message = queue_data.messages.pop(0)
    save_queue_data(queue_name, queue_data)
    return {"content": message}

@app.get("/status")
def get_status():
    """Return basic service status"""
    return {"status": "ok"}

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)
